// Before the split: one query fetched everything, even for a login check
async function login(email, password) {
  const user = await db.query(
    'SELECT * FROM users WHERE email = $1', [email]
  );
  return verifyPassword(password, user.password_hash);
}

// After the split: login only touches the narrow core table
async function login(email, password) {
  const user = await db.query(
    'SELECT id, password_hash, account_status FROM core_users WHERE email = $1',
    [email]
  );
  return verifyPassword(password, user.password_hash);
}

// A profile page now explicitly joins core identity with display data
async function getProfilePage(userId) {
  const row = await db.query(
    'SELECT c.username, p.full_name, p.avatar_url, p.bio ' +
    'FROM core_users c JOIN user_profiles p ON p.user_id = c.id ' +
    'WHERE c.id = $1',
    [userId]
  );
  return row;
}

